CREATE TYPE public.club_role AS ENUM ('super_admin','club_admin','editor','matchday_manager');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.club_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.can_manage_club(_kind text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND (role IN ('super_admin','club_admin') OR (role='editor' AND _kind IN ('news','gallery')) OR (role='matchday_manager' AND _kind IN ('fixtures','competitions','teams')))) $$;
REVOKE ALL ON FUNCTION public.can_manage_club(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_manage_club(text) TO authenticated;
CREATE TABLE public.club_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK(kind IN ('players','staff','fixtures','competitions','teams','news','gallery','honours','sponsors','settings')), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200), slug text, published boolean NOT NULL DEFAULT false, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(kind,slug));
GRANT SELECT ON public.club_records TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.club_records TO authenticated; GRANT ALL ON public.club_records TO service_role;
ALTER TABLE public.club_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_records ON public.club_records FOR SELECT TO anon USING(published);
CREATE POLICY staff_read_records ON public.club_records FOR SELECT TO authenticated USING(published OR public.can_manage_club(kind));
CREATE POLICY staff_insert_records ON public.club_records FOR INSERT TO authenticated WITH CHECK(public.can_manage_club(kind));
CREATE POLICY staff_update_records ON public.club_records FOR UPDATE TO authenticated USING(public.can_manage_club(kind)) WITH CHECK(public.can_manage_club(kind));
CREATE POLICY staff_delete_records ON public.club_records FOR DELETE TO authenticated USING(public.can_manage_club(kind));
CREATE INDEX club_records_kind_published ON public.club_records(kind,published);
CREATE TABLE public.supporters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 2 AND 120), email text NOT NULL UNIQUE CHECK(length(email)<255), location text, consent boolean NOT NULL CHECK(consent), created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.supporters TO anon; GRANT SELECT,INSERT,DELETE ON public.supporters TO authenticated; GRANT ALL ON public.supporters TO service_role;
ALTER TABLE public.supporters ENABLE ROW LEVEL SECURITY;
CREATE POLICY register_supporter ON public.supporters FOR INSERT TO anon,authenticated WITH CHECK(consent);
CREATE POLICY staff_read_supporters ON public.supporters FOR SELECT TO authenticated USING(public.can_manage_club('settings'));
CREATE POLICY staff_delete_supporters ON public.supporters FOR DELETE TO authenticated USING(public.can_manage_club('settings'));
CREATE TABLE public.contact_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 2 AND 120), email text NOT NULL CHECK(length(email)<255), subject text NOT NULL CHECK(length(subject) BETWEEN 2 AND 200), message text NOT NULL CHECK(length(message) BETWEEN 10 AND 5000), created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.contact_messages TO anon; GRANT SELECT,INSERT,DELETE ON public.contact_messages TO authenticated; GRANT ALL ON public.contact_messages TO service_role;
ALTER TABLE public.contact_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY send_contact ON public.contact_messages FOR INSERT TO anon,authenticated WITH CHECK(true);
CREATE POLICY staff_read_messages ON public.contact_messages FOR SELECT TO authenticated USING(public.can_manage_club('settings'));
CREATE POLICY staff_delete_messages ON public.contact_messages FOR DELETE TO authenticated USING(public.can_manage_club('settings'));